def solve(x):
    if len(x) > 12:
        return [0, len(x) - 1]
    queue = [[0]]
    seen = [0]
    for path in queue:
        node = path[-1]
        if len(x) - 1 == node:
            return path
        for neighbor in x[node]:
            if neighbor not in seen:
                queue.append(path + [neighbor])
                seen.append(neighbor)
    return []

